// Loads a client's consolidated.json (committed, generated by scripts/consolidate.mjs).
// Multi-client: `VITE_CLIENT` picks the folder; defaults to "tybourne". Uses an
// async loader so we get genuine loading / error / ready states.
import { useEffect, useState } from 'react';
import type { ChangeBlock, ConsolidatedData, SectorId } from '../types';

const CLIENT = (import.meta.env.VITE_CLIENT as string | undefined) || 'tybourne';

// Vite bundles every client's data file; we pick one at runtime by key.
const loaders = import.meta.glob('../../clients/*/data/consolidated.json');

export type LoadState =
  | { status: 'loading' }
  | { status: 'error'; error: string }
  | { status: 'ready'; data: ConsolidatedData };

export function useConsolidated(): LoadState {
  const [state, setState] = useState<LoadState>({ status: 'loading' });

  useEffect(() => {
    let alive = true;
    const key = `../../clients/${CLIENT}/data/consolidated.json`;
    const loader = loaders[key];
    if (!loader) {
      setState({ status: 'error', error: `No consolidated data found for client "${CLIENT}".` });
      return;
    }
    loader()
      .then((mod) => {
        if (!alive) return;
        const data = ((mod as { default?: ConsolidatedData }).default ?? mod) as ConsolidatedData;
        setState({ status: 'ready', data });
      })
      .catch((e) => {
        if (!alive) return;
        setState({ status: 'error', error: e instanceof Error ? e.message : String(e) });
      });
    return () => {
      alive = false;
    };
  }, []);

  return state;
}

// ---- selectors ----
export const bySector = (d: ConsolidatedData, sector: SectorId): ChangeBlock[] =>
  d.systems.filter((s) => s.sector === sector);

export const systemById = (d: ConsolidatedData, id: string): ChangeBlock | undefined =>
  d.systems.find((s) => s.systemId === id);

/** ok/partial blocks only (have usable numbers). */
export const live = (blocks: ChangeBlock[]): ChangeBlock[] =>
  blocks.filter((b) => b.status !== 'error' && b.changePct != null);
